    'i-label-regpassword': { en: "Create password * (exactly 8 characters, letters + numbers)", hi: "पासवर्ड बनाएं * (ठीक 8 अक्षर, अक्षर + अंक)", mr: "पासवर्ड तयार करा * (नेमके 8 अक्षरे, अक्षरे + अंक)", te: "పాస్‌వర్డ్ సృష్టించండి * (సరిగ్గా 8 అక్షరాలు, అక్షరాలు + సంఖ్యలు)", ta: "கடவுச்சொல்லை உருவாக்கவும் * (சரியாக 8 எழுத்துகள், எழுத்துகள் + எண்கள்)" },
    'i-regpassword-hint': { en: "Used if face scan fails. Remember this — write it down.", hi: "चेहरा स्कैन विफल हो तो यह उपयोग होगा। इसे याद रखें — लिख लें।", mr: "चेहरा स्कॅन अयशस्वी झाल्यास वापरला जातो. हे लक्षात ठेवा — लिहून ठेवा.", te: "ముఖ స్కాన్ విఫలమైతే ఉపయోగించబడుతుంది. దీన్ని గుర్తుంచుకోండి — రాసి ఉంచండి.", ta: "முக ஸ்கேன் தோல்வியடைந்தால் பயன்படுத்தப்படும். இதை நினைவில் கொள்ளுங்கள் — எழுதி வையுங்கள்." },
