  function applyPageLanguage(lang) {
    uiLang = lang;
    document.documentElement.lang = lang;
    try {
      sessionStorage.setItem('khataLang', lang);
    } catch (e) { /* storage unavailable (e.g. private browsing) — language just won't persist across reloads */ }

    for (const [id, texts] of Object.entries(PAGE_TEXT)) {
      const el = document.getElementById(id);
      if (el) el.textContent = texts[lang];
    }
    for (const [id, texts] of Object.entries(PAGE_PLACEHOLDERS)) {
      const el = document.getElementById(id);
      if (el) el.placeholder = texts[lang];
    }
    // address / initial_amount / registration default limit inputs are name/id-based, not translated-by-id
    const addressInput = document.querySelector('input[name="address"]');
    if (addressInput) addressInput.placeholder = lang === 'hi' ? 'जैसे: 12 एमजी रोड, बस स्टैंड के पास' : 'e.g. 12 MG Road, near bus stand';
    const regCreditLimitInput = document.getElementById('regDefaultCreditLimit');
    if (regCreditLimitInput) regCreditLimitInput.placeholder = lang === 'hi' ? 'जैसे: 2000 (या खाली छोड़ें)' : 'e.g. 2000 (or leave blank)';

    const navLangSelect = document.getElementById('navLangSelect');
    if (navLangSelect) navLangSelect.value = lang;

    applyHelpContent(lang);
    if (mainAppStarted) {
      if (typeof loadSummary === 'function') loadSummary();
      if (typeof renderDueList === 'function' && typeof allDues !== 'undefined') renderDueList(allDues);
      if (typeof loadGrowthChart === 'function') loadGrowthChart();
      if (typeof loadDueVsClearChart === 'function') loadDueVsClearChart();
      if (typeof loadProductsPage === 'function') loadProductsPage();
      if (typeof loadRequestsPage === 'function') loadRequestsPage();
      if (typeof loadPaymentsPage === 'function') loadPaymentsPage();
      if (typeof loadOnlinePaymentsPage === 'function') loadOnlinePaymentsPage();
      if (typeof loadComplaintsPage === 'function') loadComplaintsPage();
    }
    // Customer portal shop-card results, if currently on screen
    const cpResultsView = document.getElementById('cpResultsView');
    if (cpResultsView && !cpResultsView.classList.contains('hidden') && lastCpShops) {
      renderCpResults(lastCpCustomerName, lastCpShops);
    }
    // Contact Us form's category dropdown, if the panel is open
    const contactOverlayEl = document.getElementById('contactOverlay');
    if (contactOverlayEl && !contactOverlayEl.classList.contains('hidden') && typeof renderContactCategories === 'function') {
      renderContactCategories();
    }
  }

  const LANG_SWITCH_CONFIRMATIONS = {
    en: 'Language switched to English.',
    hi: 'भाषा हिंदी में बदल दी गई।',
    mr: 'भाषा मराठीमध्ये बदलली.',
    te: 'భాష తెలుగుకు మార్చబడింది.',
    ta: 'மொழி தமிழுக்கு மாற்றப்பட்டது.',
  };
  document.getElementById('navLangSelect').addEventListener('change', (e) => {
    const newLang = e.target.value;
    applyPageLanguage(newLang);
    if (typeof speak === 'function') speak(LANG_SWITCH_CONFIRMATIONS[newLang] || LANG_SWITCH_CONFIRMATIONS.en);
  });

