  function applyHelpContent(lang) {
    const body = document.getElementById('helpBody');
    if (body) body.innerHTML = HELP_CONTENT[lang] || HELP_CONTENT.en;
  }

  document.getElementById('helpListenBtn').addEventListener('click', () => {
    const plainText = document.getElementById('helpBody').textContent.replace(/\s+/g, ' ').trim();
    if (typeof speak === 'function') {
      // Temporarily force voiceEnabled on for this explicit request, even if muted
      const wasEnabled = typeof voiceEnabled !== 'undefined' ? voiceEnabled : true;
      if (typeof voiceEnabled !== 'undefined') voiceEnabled = true;
      speak(plainText);
      if (typeof voiceEnabled !== 'undefined') voiceEnabled = wasEnabled;
    }
  });

// ---- Help panel ----
  document.getElementById('helpFab').addEventListener('click', () => {
    document.getElementById('helpOverlay').classList.remove('hidden');
  });
  document.getElementById('helpClose').addEventListener('click', () => {
    document.getElementById('helpOverlay').classList.add('hidden');
  });
  document.getElementById('helpOverlay').addEventListener('click', (e) => {
    if (e.target.id === 'helpOverlay') document.getElementById('helpOverlay').classList.add('hidden');
  });
